 "content": "def transform(grid):
    # Copy the shape around the non-isolated 5 marker to each isolated 5 marker.
    pts = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v]
    fives = [(r, c) for r, c, v in pts if v == 5]
    # The donor is the 5 belonging to the larger connected component; the other 5 is a target.
    def component_size(start):
        todo = [start]
        seen = {start}
        while todo:
            r, c = todo.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p not in seen and 0 <= p[0] < len(grid) and 0 <= p[1] < len(grid[0]) and grid[p[0]][p[1]]:
                    seen.add(p); todo.append(p)
        return len(seen)
    donor = max(fives, key=component_size)
    dr, dc = donor
    out = [row[:] for row in grid]
    for ar, ac in fives:
        if (ar, ac) == donor:
            continue
        for r, c, v in pts:
            # Translate the nonzero donor component, including its central 5.
            # Do not copy independent target markers.
            if (r, c) == donor or abs(r-dr)+abs(c-dc) <= 10:
                rr, cc = ar + r-dr, ac + c-dc
                if 0 <= rr < len(grid) and 0 <= cc < len(grid[0]):
                    out[rr][cc] = v
    return out
