            for rr, cc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != 0 and (rr,cc) not in seen:
                    seen.add((rr,cc))
                    todo.append((rr,cc))
        return seen

    comps = {p: component(p) for p in fives}
    donor = max(fives, key=lambda p: len(comps[p]))
    targets = [p for p in fives if p != donor]
